import React from 'react';
import { RISKS, COLORS } from '../../constants';
import { Lang } from '../../types';
import { ShieldAlert, Activity, CheckSquare } from 'lucide-react';
import { ScatterChart, Scatter, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, Label } from 'recharts';

interface Props {
    lang: Lang;
}

const RisksView: React.FC<Props> = ({ lang }) => {

  const mapProbability = (p: string) => {
      switch(p) {
          case 'High': return 3;
          case 'Medium': return 2;
          case 'Low': return 1;
          default: return 0;
      }
  };

  const mapImpact = (i: string) => {
      switch(i) {
          case 'Critical': return 3;
          case 'Severe': return 2;
          case 'Moderate': return 1;
          default: return 0;
      }
  };

  const getRiskColor = (impact: string) => {
      switch(impact) {
          case 'Critical': return COLORS.danger;
          case 'Severe': return COLORS.secondary;
          case 'Moderate': return COLORS.primary;
          default: return COLORS.light;
      }
  };

  const chartData = RISKS.map(risk => ({
      id: risk.id,
      x: mapProbability(risk.probability),
      y: mapImpact(risk.impact),
      name: risk.risk[lang],
      probability: risk.probability,
      impact: risk.impact,
      color: getRiskColor(risk.impact)
  }));

  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const data = payload[0].payload;
      return (
        <div className="bg-slate-950 border border-slate-700 p-3 rounded shadow-xl text-xs max-w-[250px] z-50">
          <p className="font-bold text-slate-200 mb-2 border-b border-slate-800 pb-1">{data.name}</p>
          <div className="grid grid-cols-2 gap-2">
             <div>
                <span className="text-slate-500 block text-[10px] uppercase">Probability</span>
                <span className="text-slate-300 font-mono">{data.probability}</span>
             </div>
             <div>
                <span className="text-slate-500 block text-[10px] uppercase">Impact</span>
                <span className="text-slate-300 font-mono" style={{ color: data.color }}>{data.impact}</span>
             </div>
          </div>
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-br from-slate-900 to-slate-950 p-6 rounded-xl border border-slate-800">
        <h3 className="text-xl font-bold text-white mb-2 flex items-center gap-2">
            <ShieldAlert className="w-6 h-6 text-red-500" />
            {lang === 'en' ? 'Risk Management Matrix' : 'Матриця Управління Ризиками'}
        </h3>
        <p className="text-slate-400 text-sm max-w-3xl">
            {lang === 'en' 
             ? 'Comprehensive analysis of operational threats with triple-layer mitigation strategies designed for the "Consortium" scenario.'
             : 'Комплексний аналіз операційних загроз з трирівневими стратегіями пом’якшення, розробленими для сценарію "Консорціум".'}
        </p>
      </div>

      {/* Matrix Visualization */}
      <div className="bg-slate-900 p-6 rounded-xl border border-slate-800 h-[450px] flex flex-col relative overflow-hidden">
         <h4 className="text-slate-400 font-bold mb-4 text-xs uppercase tracking-wider pl-2 border-l-2 border-slate-700 flex justify-between">
            {lang === 'en' ? 'Probability vs Impact Matrix' : 'Матриця Ймовірність vs Вплив'}
            <span className="text-[10px] font-normal text-slate-500 normal-case">
                {lang === 'en' ? 'Position represents risk score' : 'Позиція відображає оцінку ризику'}
