             <div className="w-1/2 h-1/2 bg-yellow-500 absolute bottom-0 right-0"></div>
             <div className="w-1/2 h-1/2 bg-yellow-500 absolute top-0 left-0"></div>
             <div className="w-1/2 h-1/2 bg-red-500 absolute top-0 right-0"></div>
