                <ScatterChart margin={{ top: 20, right: 30, bottom: 20, left: 10 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                    <XAxis 
                        type="number" 
                        dataKey="x" 
                        name="Probability" 
                        domain={[0, 4]} 
                        ticks={[1, 2, 3]} 
